import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

# ---------- Elementwise addition custom CUDA operator ----------
elementwise_add_source = """
#include <torch/extension.h>
#include <cuda_runtime.h>

__global__ void elementwise_add_kernel(const float* a, const float* b, float* out, int size) {
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    if (idx < size) {
        out[idx] = a[idx] + b[idx];
    }
}

torch::Tensor elementwise_add_cuda(torch::Tensor a, torch::Tensor b) {
    auto size = a.numel();
    auto out = torch::zeros_like(a);

    const int block_size = 256;
    const int num_blocks = (size + block_size - 1) / block_size;

    elementwise_add_kernel<<<num_blocks, block_size>>>(a.data_ptr<float>(), b.data_ptr<float>(), out.data_ptr<float>(), size);

    return out;
}
"""

elementwise_add_cpp_source = (
    "torch::Tensor elementwise_add_cuda(torch::Tensor a, torch::Tensor b)"
)

elementwise_add = load_inline(
    name="elementwise_add",
    cpp_sources=elementwise_add_cpp_source,
    cuda_sources=elementwise_add_source,
    functions=["elementwise_add_cuda"],
    verbose=True,
    extra_cflags=[],
    extra_ldflags=[]
)

# ---------- Max reduction custom CUDA operator ----------
max_reduction_source = """
#include <torch/extension.h>
#include <cuda_runtime.h>

__global__ void max_reduction_kernel(const float* input, float* output, int B, int D1, int D2, int out_elements) {
    int idx = blockIdx.x;
    if (idx >= out_elements) return;
    int b = idx / D2;
    int d2_idx = idx % D2;
    float max_val = -1e300f;
    for (int d1 = 0; d1 < D1; ++d1) {
        int input_idx = b * D1 * D2 + d1 * D2 + d2_idx;
        float val = input[input_idx];
        if (val > max_val) max_val = val;
    }
    output[idx] = max_val;
}

torch::Tensor max_reduction_cuda(torch::Tensor x, int dim) {
    // Expecting x shape (B, D1, D2) and dim=1.
    int B = x.size(0);
    int D1 = x.size(1);
    int D2 = x.size(2);
    int out_elements = B * D2;
    auto out = torch::zeros((B, D2), dtype=x.dtype, device=x.device);
    const int block_size = 1;
    const int num_blocks = (out_elements + block_size - 1) / block_size;
    max_reduction_kernel<<<num_blocks, block_size>>>(
        x.data_ptr<float>(),
        out.data_ptr<float>(),
        B,
        D1,
        D2,
        out_elements
    );
    return out;
}
"""

max_reduction_cpp_source = (
    "torch::Tensor max_reduction_cuda(torch::Tensor x, int dim)"
)

max_reduction = load_inline(
    name="max_reduction",
    cpp_sources=max_reduction_cpp_source,
    cuda_sources=max_reduction_source,
    functions=["max_reduction_cuda"],
    verbose=True,
    extra_cflags=[],
    extra_ldflags=[]
)

class ModelNew(nn.Module):
    def __init__(self):
        super().__init__()
        self.elementwise_add = elementwise_add
        self.max_reduction = max_reduction

    def forward(self, x):
        # Reduce max over the specified dimension
        return self.max_reduction.max_reduction_cuda(x, dim=self.dim)[0]

def get_inputs():
    batch_size = 128
    dim1 = 4096
    dim2 = 4095
    x = torch.rand(batch_size, dim1, dim2).cuda()
    return [x]

def get_init_inputs():
    return []

if __name__ == "__main__":
    model = ModelNew()
    out = model(get_inputs())
